using Microsoft.EntityFrameworkCore;

// EF Core 9 Cosmos DB breaking changes addressed here:
//
// 1. Discriminator property renamed: EF Core 9 uses "$type" instead of "Discriminator".
//    For existing documents that already store "Discriminator", you must explicitly
//    configure the old property name to avoid data issues.
//
// 2. Sync Cosmos queries removed: ToList(), First(), Single(), etc. now throw
//    InvalidOperationException. You must use async variants (ToListAsync, etc.).

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.Category);

            // FIX for breaking change #1:
            // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
            // Existing documents still have "Discriminator" so we must preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// FIX for breaking change #2:
// Synchronous Cosmos DB queries are no longer supported in EF Core 9.
// All queries must use async methods.
class ProductService
{
    private readonly CosmosDbContext _db;

    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 — now throws InvalidOperationException):
    //   public List<Product> GetAll() => _db.Products.ToList();
    //   public Product? GetById(string id) => _db.Products.FirstOrDefault(p => p.Id == id);

    // AFTER (EF Core 9 — must use async):
    public async Task<List<Product>> GetAllAsync()
        => await _db.Products.ToListAsync();

    public async Task<Product?> GetByIdAsync(string id)
        => await _db.Products.FirstOrDefaultAsync(p => p.Id == id);
}

